import { writeFileSync } from 'node:fs'
import { afterAll, test } from 'vitest'
const events: unknown[]=[]
const contexts=new Map<string,unknown>()
let factory=0
const owned=test.extend<{token:number}>({token:async({task},use)=>{const value=++factory;events.push(['fixture+',task.name,value]);await use(value);events.push(['fixture-',task.name,value])}})
for(const [name,options] of [['cooperative retries',{timeout:100,retry:1}],['cooperative repeats',{timeout:120,repeats:1}]] as const){
 owned(name,options,async({task,expect:local,signal,token})=>{
  const context=task.context
  const prior=contexts.get(task.name);contexts.set(task.name,context)
  local.assertions(1)
  local(token).toBeGreaterThan(0)
  events.push(['body',task.name,task.result?.retryCount,task.result?.repeatCount,signal.aborted,prior===undefined||prior===context,local.getState().currentTestName])
  context.onTestFinished(finished=>{events.push(['finished',task.name,token,finished===context,finished.signal.aborted,local.getState().assertionCalls])})
  context.onTestFailed(failed=>{events.push(['failed',task.name,token,failed===context,failed.signal.aborted,local.getState().assertionCalls])})
  if(!signal.aborted) await new Promise<void>(resolve=>signal.addEventListener('abort',()=>{events.push(['abort',task.name,token]);resolve()},{once:true}))
  events.push(['settled',task.name,token,signal.aborted])
 })
}
owned('tail',({task,token,signal})=>events.push(['tail',task.name,token,signal.aborted]))
afterAll(()=>writeFileSync(process.env.WS1_AUDIT_FILE!,JSON.stringify(events)))
